#!/usr/bin/env python3
"""Writes src/Requestarr.Http/Frontend/Mappers/VersionLogoGlyphs.cs: the outlines of the letters the production header
logo's version bar can show ("v", the digits and ".", plus "BETA", which sets the size) and the font's kerning between
them, taken from Inter Display Black, the font of the branch labels on the dev, QA and beta logos. Requestarr draws the
bar itself, so the version always matches the one running.

Run it again only to change the font or the letters:

    pip install fonttools uharfbuzz
    python3 .github/version_logo_glyphs.py path/to/InterDisplay-Black.otf

InterDisplay-Black.otf is in extras/otf/ of Inter's release zip (github.com/rsms/inter, SIL Open Font License 1.1).
"""
import os
import sys

import uharfbuzz as hb
from fontTools.pens.boundsPen import BoundsPen
from fontTools.pens.svgPathPen import SVGPathPen
from fontTools.ttLib import TTFont

LETTERS = "v0123456789.BETA"
OUT = os.path.join(os.path.dirname(__file__), "..", "src", "Requestarr.Http", "Frontend", "Mappers", "VersionLogoGlyphs.cs")


def main(path):
    font = TTFont(path)
    glyphs = font.getGlyphSet()
    cmap = font.getBestCmap()
    name = font["name"].getDebugName(4)
    version = font["name"].getDebugName(5)

    rows = []
    for letter in LETTERS:
        glyph = cmap[ord(letter)]
        pen = SVGPathPen(glyphs, lambda v: f"{v:g}")
        glyphs[glyph].draw(pen)
        bounds = BoundsPen(glyphs)
        glyphs[glyph].draw(bounds)
        x_min, y_min, x_max, y_max = bounds.bounds
        rows.append(f'            {{ \'{letter}\', new Glyph({glyphs[glyph].width}, {x_min:g}, {y_min:g}, {x_max:g}, {y_max:g}, "{pen.getCommands()}") }},')

    # Kerning as a shaper applies it: the first letter's advance in a shaped pair, less its own advance.
    shaper = hb.Font(hb.Face(hb.Blob.from_file_path(path)))
    kerning = []
    for first in LETTERS:
        for second in LETTERS:
            buffer = hb.Buffer()
            buffer.add_str(first + second)
            buffer.guess_segment_properties()
            hb.shape(shaper, buffer, {})
            names = [font.getGlyphName(info.codepoint) for info in buffer.glyph_infos]
            positions = buffer.glyph_positions
            if names != [cmap[ord(first)], cmap[ord(second)]] or positions[0].x_offset or positions[1].x_offset:
                sys.exit(f"{first + second}: the font does more than kern this pair; the logo can't draw it")
            adjust = positions[0].x_advance - glyphs[cmap[ord(first)]].width
            if adjust:
                kerning.append(f'            {{ "{first + second}", {adjust} }},')

    text = f"""// Generated by .github/version_logo_glyphs.py from {name} ({version}). Do not edit by hand.
// Inter: Copyright (c) 2016 The Inter Project Authors (https://github.com/rsms/inter), SIL Open Font License 1.1.
using System.Collections.Generic;

namespace Requestarr.Http.Frontend.Mappers
{{
    public static class VersionLogoGlyphs
    {{
        public const int UnitsPerEm = {font["head"].unitsPerEm};

        public static readonly IReadOnlyDictionary<char, Glyph> Letters = new Dictionary<char, Glyph>
        {{
{os.linesep.join(rows)}
        }};

        public static readonly IReadOnlyDictionary<string, int> Kerning = new Dictionary<string, int>
        {{
{os.linesep.join(kerning)}
        }};

        public record Glyph(double Advance, double XMin, double YMin, double XMax, double YMax, string Path);
    }}
}}
"""
    with open(OUT, "w", newline="\n", encoding="utf-8") as f:
        f.write(text.replace(os.linesep, "\n"))
    print(f"wrote {os.path.normpath(OUT)}: {len(LETTERS)} letters from {name}")


if __name__ == "__main__":
    main(sys.argv[1])
